% runCase1a  Case 1(a), direct virulence-to-transmission coupling. GeoC, 
% invariant density, figures and the alternative-methods table.
%
% CALLS     generateCase1Series, estimateGeoC, plotLocalSlopeDiagnostics2x2, estimateInvariantDensity2D,
%           batlow, addPanelLabel, transferEntropyKSG, ccmSkill, grangerLinearF, makeAltMethodsLatexTable
% INPUT     none (the benchmark record is generated by generateCase1Series('1a'))
% OUTPUT    ResultsCaseIa/FigureGeoCCase1a.png, FigureCase1aInvariantDen.png, 
%           AltMethodsCase1a.mat, TableAltMethodsCase1a.tex
%           and the GeoC table printed in the command window

clear; close all; clc;
set(groot, 'defaultTextInterpreter', 'latex');
set(groot, 'defaultAxesTickLabelInterpreter', 'latex');

outDir = 'ResultsCaseIa';
if ~exist(outDir, 'dir'), mkdir(outDir); end
betaMax = 1.5;

%%
[Mu, Beta] = generateCase1Series('1a');
d2Opts = {'MinPlateauLength', 10, 'SlopeCVmax', 0.15, 'MaxSlopeDrift', 0.10, 'R2min', 0.98, 'Cmax', 0.20, 'MinPairs', 1000};
[T, details] = estimateGeoC(Mu, Beta, 'Subsample', 2500, 'Seed', 2, d2Opts{:});
disp(T);

fig = plotLocalSlopeDiagnostics2x2(details);
exportgraphics(fig, fullfile(outDir, 'FigureGeoCCase1a.png'), 'Resolution', 600);
close(fig);

%%
invOut = estimateInvariantDensity2D(Mu, Beta, 'NBins', 100, 'Bounds', [0, 0; 1, betaMax]);

fig = figure('Color', 'w', 'Units', 'centimeters', 'Position', [2.5, 2.5, 18.0, 11.5], 'Renderer', 'painters');
tl = tiledlayout(fig, 2, 2, 'TileSpacing', 'compact', 'Padding', 'compact');
fontName = 'Arial'; tickSize = 8.5; labelSize = 10;
muColor = [0.20 0.35 0.55]; betaColor = [0.70 0.35 0.20];

ax1 = nexttile(tl, 1, [2 1]);
plot(ax1, Mu, Beta, '.', 'Color', [0.15 0.15 0.15], 'MarkerSize', 2.5);
xlabel(ax1, '$\mu$', 'FontName', fontName, 'FontSize', labelSize);
ylabel(ax1, '$\beta$', 'FontName', fontName, 'FontSize', labelSize);
xlim(ax1, [0 1]); ylim(ax1, [0 betaMax]);
styleAxes(ax1, fontName, tickSize);
addPanelLabel(ax1, '(a)', -0.17, 0.95, 11);

ax2 = nexttile(tl, 2);
contourf(ax2, invOut.MU, invOut.BETA, invOut.invariantDensity, 25, 'LineColor', 'none');
colormap(ax2, batlow(256));
xlabel(ax2, '$\mu$', 'FontName', fontName, 'FontSize', labelSize);
ylabel(ax2, '$\beta$', 'FontName', fontName, 'FontSize', labelSize);
xlim(ax2, [0 1]); ylim(ax2, [0 betaMax]);
styleAxes(ax2, fontName, tickSize);
cb = colorbar(ax2, 'eastoutside');
cb.Label.String = '$p^*(\mu,\beta)$'; cb.Label.Interpreter = 'latex';
cb.Label.FontName = fontName; cb.Label.FontSize = labelSize;
cb.FontName = fontName; cb.FontSize = 7.5; cb.LineWidth = 0.6; cb.TickDirection = 'out';
addPanelLabel(ax2, '(b)', -0.25, 1.035, 11);

ax3 = nexttile(tl, 4);
yyaxis(ax3, 'left');
hMu = plot(ax3, invOut.muVec, invOut.f_mu_marginal, '-', 'Color', muColor, 'LineWidth', 1.65, 'DisplayName', 'Virulence, $\mu$');
ylabel(ax3, '$p^*_{\mu}(\mu)$', 'FontName', fontName, 'FontSize', labelSize);
ax3.YColor = muColor;
yyaxis(ax3, 'right');
hBeta = plot(ax3, invOut.betaVec, invOut.f_beta_marginal, '--', 'Color', betaColor, 'LineWidth', 1.65, 'DisplayName', 'Transmission, $\beta$');
ylabel(ax3, '$p^*_{\beta}(\beta)$', 'FontName', fontName, 'FontSize', labelSize);
ax3.YColor = betaColor;
xlabel(ax3, '$\mu,\ \beta$', 'FontName', fontName, 'FontSize', labelSize);
xlim(ax3, [0 betaMax]);
styleAxes(ax3, fontName, tickSize, false);
legend(ax3, [hMu hBeta], 'Location', 'north', 'Interpreter', 'latex', 'Box', 'off', ...
    'FontName', fontName, 'FontSize', 7.5, 'NumColumns', 2);
addPanelLabel(ax3, '(c)', -0.17, 0.95, 11);

exportgraphics(fig, fullfile(outDir, 'FigureCase1aInvariantDen.png'), 'Resolution', 600, 'BackgroundColor', 'white');
close(fig);

%%
nSur = 20; Lsizes = [100 300 1000 3000]; Eemb = 3;
A.geoc.b2m = T.RawValue(strcmp(T.Term, 'GeoC_beta_to_mu'));
A.geoc.m2b = T.RawValue(strcmp(T.Term, 'GeoC_mu_to_beta'));
A.te.b2m = transferEntropyKSG(Beta, Mu, 'Subsample', 2000, 'K', 4, 'NumSurrogates', nSur, 'Seed', 1);
A.te.m2b = transferEntropyKSG(Mu, Beta, 'Subsample', 2000, 'K', 4, 'NumSurrogates', nSur, 'Seed', 1);
A.ccm.b2m = ccmSkill(Beta, Mu, 'E', Eemb, 'LibSizes', Lsizes, 'Seed', 1);
A.ccm.m2b = ccmSkill(Mu, Beta, 'E', Eemb, 'LibSizes', Lsizes, 'Seed', 1);
A.gr.b2m = grangerLinearF(Beta, Mu, 1);
A.gr.m2b = grangerLinearF(Mu, Beta, 1);
A.nSurrogates = nSur;
A.Lmin = A.ccm.m2b.L(1);
A.Lmax = A.ccm.m2b.L(end);
save(fullfile(outDir, 'AltMethodsCase1a.mat'), 'A');
makeAltMethodsLatexTable(A, fullfile(outDir, 'TableAltMethodsCase1a.tex'), 'Case~1(a)', 'SItab:alt_methods_case1a');
%%
function styleAxes(ax, fontName, tickSize, squareAspect)
if nargin < 4, squareAspect = true; end
set(ax, 'FontName', fontName, 'FontSize', tickSize, 'LineWidth', 0.75, 'TickDir', 'out', ...
    'TickLength', [0.015 0.015], 'Box', 'off', 'Layer', 'top', 'XMinorTick', 'on', 'YMinorTick', 'on');
grid(ax, 'off');
if squareAspect, pbaspect(ax, [1 1 1]); end
end
